const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format((v||0)/100);
const date=v=>new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(v));
const cents=v=>{if(!/^\d+(?:[.,]\d{1,2})?$/.test(String(v)))throw Error('Usa un importe positivo con hasta dos decimales.');return Math.round(Number(String(v).replace(',','.'))*100);};
const paths={lock:'M6 10V6a6 6 0 0 1 12 0v4M4 10h16v12H4z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',list:'M8 5h13M8 12h13M8 19h13M2 5h1m-1 7h1m-1 7h1',edit:'m4 16 12-12 4 4L8 20H4zM14 6l4 4',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15',save:'M3 3h15l3 3v15H3zM7 3v6h10V3M7 21v-8h10v8',coffee:'M3 7h14v9a6 6 0 0 1-12 0V7Zm14 1h2a3 3 0 1 1 0 6h-2M7 1v2m5-2v2',tables:'M4 4h16v16H4z M8 1v3m8-3v3M8 20v3m8-3v3M1 8h3m-3 8h3m16-8h3m-3 8h3',sales:'M3 5h18v14H3z M3 10h18m-14 5h4',products:'m12 2 10 5v11l-10 5-10-5V7z M2 7l10 5 10-5M12 12v11',contacts:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 22v-3a8 8 0 0 1 16 0v3',reports:'M3 2v19h19M7 17v-5m5 5V7m5 10V4',cash:'M3 7h18v14H3z M7 7V3h10v4m-8 6h6',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M5 5l3 3m8 8 3 3M5 19l3-3m8-8 3-3M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',purchases:'M5 7h14l2 15H3z M8 8V5a4 4 0 0 1 8 0v3',kitchen:'M4 11a4 4 0 0 1 0-8 4 4 0 0 1 8 0 4 4 0 0 1 8 0 4 4 0 0 1 0 8v10H4z M4 17h16',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 4v16M4 12h16',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-2 4 7 7',check:'m4 12 5 5L20 6',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',logout:'M9 3H3v18h6M8 12h13m-5-5 5 5-5 5',close:'m6 6 12 12M6 18 18 6',print:'M6 8V2h12v6M6 17H2V8h20v9h-4M6 14h12v8H6z',quote:'M5 2h14v20l-4-3-3 3-3-3-4 3z M8 7h8m-8 5h8',refresh:'M20 10a8 8 0 1 0-1 8M20 3v7h-7',menu:'M3 5h18M3 12h18M3 19h18'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.tables}"/></svg>`;
const brand=()=>`<span class="brand"><span class="raven"></span>RAVEN <small>POS</small></span>`;
const btn=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value='')=>`<label class="field"><span>${label}</span><select name="${name}" aria-label="${esc(label)}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
let me=null,tenant=null,state=null,view='tables',draft=null,editorTab='products',category='Todas',query='',dirty=false,busy=false,submitting=false,logoValue='',saleFilter='',catalogView='list',tableFilter='all',selectedArea='Todos';
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=error?'error visible':'visible';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000);}
async function api(path,{method='GET',body}={}){const response=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':me?.csrf||''},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok){if(response.status===401&&path!=='login'){me=null;login();}throw Error(data.error||'No se pudo completar la solicitud.');}return data;}
const endpoint=p=>'t/'+tenant.slug+'/'+p;
const can=p=>state?.permissions.includes(p);
async function refresh(){state=await api(endpoint('state'));render();}
async function mutate(path,body,message='Guardado'){if(busy)return;busy=true;document.body.classList.add('busy');try{const result=await api(endpoint(path),{method:'POST',body});await refresh();if(message)toast(message);return result;}finally{busy=false;document.body.classList.remove('busy');}}
async function boot(){try{me=await api('me');companies();}catch{login();}}
function login(){tenant=null;state=null;app.innerHTML=`<main class="login-layout"><section class="login-story">${brand()}<div><span class="eyebrow">TU NEGOCIO, BAJO CONTROL</span><h1>Un nuevo ritmo.<br><em>Tu mismo negocio.</em></h1><p>Pedidos, personas y decisiones.<br>Todo en su lugar.</p></div><div class="login-glass"><span class="status-dot"></span><div><strong>Un espacio para cada empresa</strong><p>Acceso privado · Datos separados · Tu identidad</p></div>${icon('arrow')}</div><small>Raven POS / Espacio de trabajo</small></section><section class="login-form-wrap"><form id="login-form"><span class="eyebrow">BIENVENIDO A RAVEN</span><h2>Vamos a trabajar.</h2><p>Ingresa con la cuenta de tu empresa.</p>${field('Correo electrónico','email','','email','required autocomplete="username"')}${field('Contraseña','password','','password','required autocomplete="current-password"')}<label class="check"><input type="checkbox" id="show-password"> Mostrar contraseña</label><button class="btn primary" type="submit">Ingresar ${icon('arrow')}</button><p id="login-error" class="error-text" role="alert"></p><p class="help">¿Necesitas acceso o recuperar tu cuenta?<br>Solicítalo al administrador de Raven.</p></form><span class="local-label">Entorno local de evaluación</span></section></main>`;$('#show-password').onchange=e=>$('#login-form [name=password]').type=e.target.checked?'text':'password';}
function companies(){draft=null;dirty=false;app.innerHTML=`<main class="company-page"><header>${brand()}${btn('Cerrar sesión','logout','quiet')}</header><div class="company-intro"><span class="eyebrow">TU ESPACIO DE TRABAJO</span><h1>Hola, ${esc(me.user.name.split(' ')[0])}.</h1><p>Elige el negocio que vas a administrar.</p></div><div class="company-list">${me.tenants.map(t=>{const active=t.status==='active'&&Date.parse(t.expires_at)>Date.now();return`<button class="company-card glass" data-action="company" data-id="${esc(t.id)}" ${active?'':'disabled'}><span class="company-avatar">${esc(t.name.slice(0,2).toUpperCase())}</span><span><strong>${esc(t.name)}</strong><small>${esc(t.role)} · ${active?'Acceso activo':'Acceso pendiente o vencido'}</small></span>${icon('arrow')}</button>`;}).join('')}</div><p class="help">Cada empresa conserva sus propios productos, usuarios y operaciones.<br>La activación se realiza después de verificar el pago.</p></main>`;}
const sections=[['tables','Mesas','tables','orders'],['sales','Ventas','sales','reports'],['documents','Comprobantes','quote','reports'],['quotes','Cotizaciones','quote','orders'],['kitchen','Cocina','kitchen','kitchen'],['purchases','Compras','purchases','purchases'],['products','Productos','products','products'],['contacts','Clientes y proveedores','contacts','contacts'],['reports','Reportes','reports','reports'],['cash','Caja','cash','cash'],['users','Equipo','contacts','users'],['settings','Configuración','settings','settings']];
function render(){
 if(!state)return;
 const suite=['tables','sales','documents','quotes'].includes(view)||!!draft;
 const title=draft?'Pedido '+(draft.number?String(draft.number).padStart(4,'0'):'nuevo'):sections.find(s=>s[0]===view)?.[1]||'Mesas';
 const nav=[['tables','Ventas','sales','orders'],...sections.filter(s=>!['tables','sales','documents','quotes'].includes(s[0]))];
 app.innerHTML=`<div class="workspace ${draft?'editing':''}"><aside class="sidebar"><a href="#" class="brand-link" data-action="companies">${brand()}</a><button class="tenant-switch" data-action="companies" aria-label="Cambiar empresa: ${esc(state.tenant.name)}">${state.tenant.logo?`<img src="${esc(state.tenant.logo)}" alt="">`:`<span class="tenant-initial">${esc(state.tenant.name.slice(0,2).toUpperCase())}</span>`}<span><strong>${esc(state.tenant.name)}</strong><small>Mi espacio de trabajo ${icon('arrow')}</small></span></button><span class="nav-label">GESTIONA TU NEGOCIO</span><nav aria-label="Módulos">${nav.filter(s=>can(s[3])).map(([key,label,i])=>`<button data-action="view" data-view="${key}" aria-label="${label}" title="${label}" class="nav-item ${(key==='tables'?suite:key===view)&&!draft?'active':draft&&key==='tables'?'active':''}" ${(key==='tables'?suite:key===view)?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='kitchen'?`<small>${state.orders.filter(o=>!['draft','served'].includes(o.kitchen)&&o.status==='open').length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom-label"><span class="status-dot"></span> Tu operación, conectada.</div><div class="sidebar-foot"><span class="user-avatar">${esc(me.user.name.slice(0,1))}</span><div><strong>${esc(me.user.name)}</strong><small>${esc(state.role)}</small></div><button class="icon-btn" data-action="logout" aria-label="Cerrar sesión">${icon('logout')}</button></div></aside><div class="workspace-main"><header class="topbar"><div class="topbar-context"><span class="eyebrow">${esc(state.tenant.name)} / ${suite?'VENTAS':'ADMINISTRACIÓN'}</span><h1>${draft?(draft.table_id?'Mesa '+esc(state.tables.find(t=>t.id===draft.table_id)?.name):'Venta directa'):esc(title)}</h1></div><div class="top-actions">${can('cash')?`<button data-action="view" data-view="cash" class="cash-badge ${state.shift?'open':''}"><i></i>${state.shift?'Caja abierta':'Abrir caja'}</button>`:''}<button class="icon-btn" data-action="refresh" aria-label="Actualizar datos" title="Actualizar">${icon('refresh')}</button><label class="theme-select"><span class="sr-only">Apariencia</span><select id="theme"><option value="auto">Automático</option><option value="light">Claro</option><option value="dark">Oscuro</option></select></label>${can('orders')&&!draft?btn(icon('plus')+' Nueva venta','new-order','primary','aria-label="Nueva venta"'):''}</div></header>${suite&&!draft?`<nav class="sales-tabs" aria-label="Vistas de ventas">${[['tables','Mesas','orders'],['sales','Ventas','reports'],['documents','Comprobantes','reports'],['quotes','Cotizaciones','orders']].filter(s=>can(s[2])).map(([key,label])=>`<button class="${view===key?'selected':''}" data-action="view" data-view="${key}" ${view===key?'aria-current="page"':''}>${label}</button>`).join('')}<span class="sales-tabs-note">${icon('lock')} Espacio privado</span></nav>`:''}<main class="content">${draft?editor():({tables:tablesPage,sales:salesPage,documents:documentsPage,quotes:quotesPage,kitchen:kitchenPage,purchases:purchasesPage,products:productsPage,contacts:contactsPage,reports:reportsPage,cash:cashPage,users:usersPage,settings:settingsPage}[view]||tablesPage)()}</main><footer class="workspace-footer"><span><i class="status-dot"></i> Guardado en el servidor local</span><span>RAVEN POS · PEN / S/ · ${esc(state.role)}</span></footer></div></div>`;
 try{$('#theme').value=localStorage.getItem('raven-pos-theme')||'auto';}catch{}
 $('#theme').onchange=e=>window.ravenTheme(e.target.value);
 if($('#product-search'))$('#product-search').oninput=e=>{query=e.target.value;$('#product-grid').innerHTML=productButtons();};
 if($('#sale-search'))$('#sale-search').oninput=e=>{saleFilter=e.target.value;$('#sale-rows').innerHTML=salesRows();};
 document.querySelectorAll('.table-scroll').forEach(el=>{el.tabIndex=0;el.setAttribute('role','region');el.setAttribute('aria-label','Tabla de '+title);});
 if($('#logo-file'))$('#logo-file').onchange=readLogo;
 if($('#kitchen-note'))$('#kitchen-note').oninput=e=>{draft.notes=e.target.value;dirty=true;$('.save-note').innerHTML='<span class="unsaved-dot"></span> Cambios sin guardar';};
}
const intro=(eyebrow,title,description,actions='')=>`<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p>${description}</p></div><div class="intro-actions">${actions}</div></div>`;
function tablesPage(){
 const tables=state.tables.filter(t=>t.active),open=state.orders.filter(o=>o.status==='open'),areas=[...new Set(tables.map(t=>t.area))];
 const shown=tables.filter(t=>(selectedArea==='Todos'||t.area===selectedArea)&&(tableFilter==='all'||(tableFilter==='occupied')===open.some(o=>o.table_id===t.id)));
 return `<section class="salon-stage"><div class="salon-watermark" aria-hidden="true">Salón.</div><div class="salon-toolbar"><div class="salon-title"><span class="eyebrow">LA EXPERIENCIA, MESA A MESA</span><h2>Tu salón, en orden.</h2></div><div class="salon-filters" aria-label="Filtrar mesas">${[['all','Todas'],['free','Disponibles'],['occupied','En atención']].map(([key,label])=>btn(label,'table-filter',tableFilter===key?'selected':'',`data-filter="${key}" aria-pressed="${tableFilter===key}"`)).join('')}</div></div><div class="table-summary"><span><i class="legend free"></i> ${tables.length-open.filter(o=>o.table_id).length} disponibles</span><span><i class="legend occupied"></i> ${open.filter(o=>o.table_id).length} en atención</span><span>Consumo abierto <strong>${money(open.reduce((s,o)=>s+o.total,0))}</strong></span></div><div class="tables-grid">${shown.map(t=>{const order=open.find(o=>o.table_id===t.id),customer=state.contacts.find(c=>c.id===order?.customer_id);return `<article class="table-card glass ${order?'occupied':''}"><button class="table-main" data-action="table" data-id="${t.id}"><span class="table-state"><i></i>${order?'En atención':'Disponible'}</span><span class="table-drawing">${icon('tables')}</span><strong>${esc(t.name)}</strong><span class="table-customer">${esc(customer?.name||'Sin cliente asignado')}</span><span class="table-meta">${order?money(order.total):'Vacía'}</span><span class="table-bottom"><span>${esc(t.area)} · ${t.capacity} pers.</span>${icon('arrow')}</span></button>${can('tables')?`<details class="table-dropdown"><summary aria-label="Opciones de mesa ${esc(t.name)}">⌄</summary><div>${btn('Editar mesa','edit-table','quiet',`data-id="${t.id}"`)}${btn(t.active?'Desactivar':'Activar','toggle-table','quiet',`data-id="${t.id}"`)}${btn('Administrar','edit-table','quiet',`data-id="${t.id}"`)}</div></details>`:''}</article>`;}).join('')||'<p class="empty">No hay mesas en este filtro.</p>'}</div><div class="salon-bottom glass"><div class="area-selector">${icon('grid')}${select('Ambiente','area-filter',[['Todos','Todos los ambientes'],...areas.map(a=>[a,a])],selectedArea)}</div><div>${can('tables')?btn(icon('plus')+' Agregar mesa','edit-table','quiet')+btn(icon('settings')+' Administrar','manage-tables','outline'):''}</div></div></section><section class="open-counter"><div><h3>Pedidos en mostrador</h3><p>Ventas que continúan sin ocupar una mesa.</p></div><div>${open.filter(o=>!o.table_id).map(o=>btn('#'+o.number+' · '+money(o.total),'load-order','outline',`data-id="${o.id}"`)).join('')||'<span class="help">No hay pedidos pendientes.</span>'}</div></section>`;
}
function newDraft(tableId=null){draft={table_id:tableId,customer_id:null,items:[],discount:0,notes:'',guests:1,status:'open'};editorTab='products';category='Todas';query='';dirty=false;render();}
const total=()=>draft.items.reduce((s,i)=>s+i.price*i.quantity,0)-(draft.discount||0);
function editor(){
 const table=state.tables.find(t=>t.id===draft.table_id);
 return `<div class="order-layout"><section class="order-panel glass" aria-label="Detalle del pedido"><div class="order-heading">${btn('←','back','icon-btn','aria-label="Volver a mesas"')}<div class="order-name"><strong>${draft.status==='quote'?'Cotización':table?'Mesa '+esc(table.name):'Mostrador'}</strong><small>${draft.number?'Pedido #'+String(draft.number).padStart(4,'0'):'Nuevo pedido'}</small></div>${btn(icon('settings'),'order-options','icon-btn','aria-label="Opciones del pedido" title="Mesa, personas, cliente y descuento"')}<span class="order-date">${draft.guests||1} pers.<span>${new Intl.DateTimeFormat('es-PE',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'America/Lima'}).format(new Date())}</span><strong>S/</strong></span></div><div class="order-lines">${draft.items.length?draft.items.map((i,n)=>`<article class="order-line">${btn(icon('trash'),'remove-item','icon-btn',`data-index="${n}" aria-label="Eliminar ${esc(i.name)}"`)}<div class="line-title"><strong>${esc(i.name)}</strong><small>${money(i.price)} por unidad${i.note?' · '+esc(i.note):''}</small></div><div class="quantity">${btn('−','quantity','',`data-index="${n}" data-delta="-1" aria-label="Quitar una unidad de ${esc(i.name)}"`)}<span>${i.quantity}</span>${btn('+','quantity','',`data-index="${n}" data-delta="1" aria-label="Agregar una unidad de ${esc(i.name)}"`)}</div><strong>${money(i.price*i.quantity)}</strong>${btn(icon('edit'),'line-note','icon-btn',`data-index="${n}" aria-label="Observaciones de ${esc(i.name)}"`)}</article>`).join(''):`<div class="empty-cart"><span class="empty-glass-orb">${icon('sales')}</span><h3>Tu próximo pedido empieza aquí.</h3><p>Selecciona productos del catálogo.<br>Nosotros ponemos todo en su lugar.</p></div>`}</div><div class="order-checkout"><div class="order-total">${btn(draft.discount?'Descuento '+money(draft.discount):'Aplicar descuento','order-options','quiet')}<span>Total <strong>${money(total())}</strong></span></div><label class="kitchen-message">${icon('kitchen')}<textarea id="kitchen-note" rows="2" maxlength="1000" placeholder="Indicaciones para la cocina" aria-label="Indicaciones para la cocina">${esc(draft.notes)}</textarea>${draft.status==='open'?btn(icon('arrow'),'send-kitchen','icon-btn',`aria-label="Guardar y enviar a cocina" ${draft.items.length?'':'disabled'}`):''}</label><div class="order-actions">${btn(icon('print')+' Precuenta','prebill','outline',draft.id?'':'disabled')}${draft.status==='quote'?btn('Convertir a pedido','convert-quote','primary',draft.items.length?'':'disabled'):can('checkout')?btn(icon('check')+' Finalizar','finalize','primary',draft.items.length?'':'disabled'):btn('Enviar a cocina','send-kitchen','primary',draft.items.length?'':'disabled')}${btn(icon('save')+' Guardar','save-order','save-btn',draft.items.length?'':'disabled')}</div><p class="save-note">${dirty?'<span class="unsaved-dot"></span> Cambios sin guardar':draft.id?icon('check')+' Pedido guardado':'Tu pedido se guardará cuando lo confirmes.'}</p></div></section><section class="catalog-panel" aria-label="Productos y pagos"><div class="editor-tabs" role="tablist" aria-label="Sección del pedido"><button type="button" id="tab-products" role="tab" aria-controls="editor-content" tabindex="${editorTab==='products'?0:-1}" aria-selected="${editorTab==='products'}" data-action="products-tab">${icon('products')} Productos</button>${can('checkout')&&draft.status!=='quote'?`<button type="button" id="tab-payments" role="tab" aria-controls="editor-content" tabindex="${editorTab==='payments'?0:-1}" aria-selected="${editorTab==='payments'}" data-action="pay-tab" ${draft.items.length?'':'disabled'}>${icon('cash')} Pagos</button>`:''}</div><div class="editor-content" role="tabpanel" id="editor-content" aria-labelledby="${editorTab==='products'?'tab-products':'tab-payments'}">${editorTab==='products'?`<div class="category-list">${['Todas',...new Set(state.products.filter(p=>p.active).map(p=>p.category))].map(c=>btn((c==='Todas'?icon('grid'):c==='Bebidas'?icon('coffee'):icon('products'))+' '+esc(c),'category',category===c?'selected':'',`data-category="${esc(c)}" aria-pressed="${category===c}"`)).join('')}</div><div class="catalog-search"><label class="search-box">${icon('search')}<input id="product-search" type="search" value="${esc(query)}" placeholder="Buscar producto" aria-label="Buscar producto"></label><div class="view-switch" aria-label="Presentación de productos">${btn(icon('list'),'catalog-list',catalogView==='list'?'selected':'','aria-label="Ver productos en lista" aria-pressed="'+(catalogView==='list')+'"')}${btn(icon('grid'),'catalog-grid',catalogView==='grid'?'selected':'','aria-label="Ver productos en cuadrícula" aria-pressed="'+(catalogView==='grid')+'"')}</div></div><div class="product-grid ${catalogView==='list'?'list-view':''}" id="product-grid">${productButtons()}</div>`:paymentForm()}</div></section></div>`;
}
function productButtons(){return state.products.filter(p=>p.active&&(category==='Todas'||p.category===category)&&p.name.toLowerCase().includes(query.toLowerCase())).map(p=>`<button class="product-card glass" data-action="add-product" data-id="${p.id}">${p.image?`<img src="/assets/${p.image}.jpg" alt="" loading="lazy">`:`<span class="product-placeholder">${icon('products')}</span>`}<span class="product-copy"><small>${esc(p.category)}</small><strong>${esc(p.name)}</strong><span>${money(p.price)}<i>+</i></span><small>${p.track_stock?p.stock+' disponibles':'Sin control de stock'}</small></span></button>`).join('')||'<p class="empty">No se encontraron productos.</p>';}
function paymentForm(){return `<form id="payment-form" class="payment-form"><div class="payment-heading"><span class="eyebrow">REGISTRO DE PAGO</span><h2>Todo listo para finalizar.</h2><p>Una cuenta · ${money(total())}</p></div><div class="document-choice"><span>${icon('quote')} Ticket interno</span><small>Sin validez tributaria</small></div>${state.shift?'':'<p class="notice">Abre una caja para registrar este cobro.</p>'}<div class="payment-rows"><div class="payment-row">${select('Medio de pago','method',[['efectivo','Efectivo'],['tarjeta','Tarjeta'],['yape','Yape'],['plin','Plin'],['transferencia','Transferencia']])}${field('Importe aplicado S/','amount',(total()/100).toFixed(2),'number',`min="${total()===0?'0':'0.01'}" step="0.01" required`)}</div></div><div class="payment-additions">${btn(icon('plus')+' Dividir pago','add-payment','quiet')}${btn(icon('plus')+' Propina','focus-tip','quiet')}</div><div class="form-grid">${field('Efectivo recibido S/','received','','number','min="0" step="0.01" placeholder="Opcional"')}${field('Propina S/','tip','0.00','number','min="0" step="0.01"')}</div><div class="payment-feedback" aria-live="polite"></div><div class="payment-client">${select('Cliente del pedido','customer_id',[['','Consumidor final'],...state.contacts.filter(c=>c.type!=='proveedor').map(c=>[c.id,c.name])],draft.customer_id||'')}${btn(icon('plus'),'edit-contact','icon-btn','aria-label="Agregar cliente"')}</div><p class="help">Registra un pago ya recibido. No se realizan cargos en tarjetas ni consultas a SUNAT.</p><button type="submit" class="btn primary wide" ${state.shift?'':'disabled'}>${icon('check')} Confirmar pago · ${money(total())}</button></form>`;}
function salesRows(){return state.sales.filter(s=>String(s.number).includes(saleFilter)||state.contacts.find(c=>c.id===s.customer_id)?.name.toLowerCase().includes(saleFilter.toLowerCase())).map(s=>`<tr><td><strong>#${String(s.number).padStart(5,'0')}</strong><small>${s.status==='void'?'Anulada':'Venta registrada'}</small></td><td>${esc(state.contacts.find(c=>c.id===s.customer_id)?.name||'Consumidor final')}</td><td>${money(s.total)}${s.tip?`<small>Propina ${money(s.tip)}</small>`:''}</td><td>${date(s.created_at)}</td><td><span class="pill ${s.status==='paid'?'success':''}">${s.status==='paid'?'Pagada':'Anulada'}</span></td><td><div class="row-actions">${btn(icon('print'),'receipt','icon-btn',`data-id="${s.order_id}" aria-label="Ver ticket ${s.number}"`)}${can('void')&&s.status==='paid'?btn('Anular','void','quiet',`data-id="${s.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hay ventas registradas.</td></tr>';}
function salesPage(){return`${intro('HISTORIAL DE OPERACIONES','Cada venta, con su contexto.','Consulta hasta las 500 ventas más recientes.',btn('Exportar CSV','export-sales','outline'))}<div class="panel"><label class="search-box">${icon('search')}<input id="sale-search" placeholder="Buscar por número o cliente" aria-label="Buscar ventas" value="${esc(saleFilter)}"></label><div class="table-scroll"><table><thead><tr><th>Venta</th><th>Cliente</th><th>Total</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="sale-rows">${salesRows()}</tbody></table></div></div>`;}
function documentsPage(){return`${intro('COMPROBANTES INTERNOS','Tus tickets, organizados.','La emisión electrónica SUNAT no está habilitada en esta versión.')}<p class="notice">Los documentos disponibles son tickets y precuentas internos. No se emiten boletas ni facturas tributarias.</p>${salesPage().replace(/^[\s\S]*?<div class="panel">/,'<div class="panel">')}`;}
function quotesPage(){return`${intro('ANTES DE LA VENTA','Cotiza con claridad.','Guarda una propuesta y conviértela en pedido cuando se confirme.',btn('Nueva cotización','new-quote','primary'))}<div class="card-list">${state.orders.filter(o=>o.status==='quote').map(o=>`<article class="panel"><span class="eyebrow">COTIZACIÓN ${o.number}</span><h3>${money(o.total)}</h3><p>${esc(state.contacts.find(c=>c.id===o.customer_id)?.name||'Sin cliente asignado')}</p>${btn('Abrir cotización','load-order','outline',`data-id="${o.id}"`)}</article>`).join('')||'<p class="empty">No hay cotizaciones pendientes.</p>'}</div>`;}
function kitchenPage(){return`${intro('EL RITMO DE COCINA','Cada pedido tiene su momento.','Actualiza la vista para recibir las últimas comandas.',btn('Actualizar cocina','refresh','outline'))}<div class="kitchen-board">${[['received','Recibido'],['preparing','Preparando'],['ready','Listo']].map(([status,title])=>`<section><h3>${title}</h3>${state.orders.filter(o=>o.kitchen===status&&o.status==='open').map(o=>`<article class="panel kitchen-order"><span class="eyebrow">PEDIDO ${o.number}</span><h3>${o.table_id?'Mesa '+esc(state.tables.find(t=>t.id===o.table_id)?.name):'Mostrador'}</h3>${o.items.map(i=>`<p><strong>${i.quantity} × ${esc(i.name)}</strong>${i.note?'<small>'+esc(i.note)+'</small>':''}</p>`).join('')}${o.notes?`<p class="notice">${esc(o.notes)}</p>`:''}${btn(status==='received'?'Comenzar':status==='preparing'?'Marcar listo':'Entregado','kitchen-next','primary',`data-id="${o.id}"`)}</article>`).join('')||'<p class="empty">Sin pedidos.</p>'}</section>`).join('')}</div>`;}
function productsPage(){return`${intro('CATÁLOGO E INVENTARIO','Tu carta, al día.','Los precios se guardan en soles. El stock se descuenta al cobrar.',btn('Agregar producto','edit-product','primary'))}<div class="panel table-scroll"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td><div class="product-cell">${p.image?`<img src="/assets/${p.image}.jpg" alt="">`:icon('products')}<strong>${esc(p.name)}</strong></div></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${p.track_stock?p.stock:'No controlado'}</td><td>${p.active?'Activo':'Desactivado'}</td><td>${btn('Editar','edit-product','quiet',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function contactsPage(){return`${intro('PERSONAS Y EMPRESAS','Relaciones bien organizadas.','Datos ingresados manualmente; no se realiza una consulta automática a SUNAT.',btn('Nuevo contacto','edit-contact','primary'))}<div class="panel table-scroll"><table><thead><tr><th>Nombre</th><th>Tipo</th><th>Documento</th><th>Contacto</th><th></th></tr></thead><tbody>${state.contacts.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.address)}</small></td><td>${esc(c.type)}</td><td>${esc(c.document_type)} ${esc(c.document)}</td><td>${esc(c.email)}<small>${esc(c.phone)}</small></td><td>${btn('Editar','edit-contact','quiet',`data-id="${c.id}"`)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Agrega tu primer cliente o proveedor.</td></tr>'}</tbody></table></div>`;}
function purchasesPage(){return`${intro('ENTRADAS DE INVENTARIO','Cada compra suma.','Registra la recepción de productos. El desembolso de efectivo se registra por separado en Caja.',btn('Registrar compra','new-purchase','primary'))}<div class="panel table-scroll"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Cantidad</th><th>Total</th><th>Referencia</th></tr></thead><tbody>${state.purchases.map(p=>`<tr><td>${date(p.created_at)}</td><td>${esc(state.products.find(x=>x.id===p.product_id)?.name)}</td><td>${p.quantity}</td><td>${money(p.total)}</td><td>${esc(p.reference)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay compras registradas.</td></tr>'}</tbody></table></div>`;}
function reportsPage(){const sales=state.sales.filter(s=>s.status==='paid');const sum=sales.reduce((n,s)=>n+s.total,0),tips=sales.reduce((n,s)=>n+s.tip,0);const methods={};for(const s of sales)for(const p of s.payments)methods[p.method]=(methods[p.method]||0)+p.amount;return`${intro('UNA VISTA MÁS CLARA','Los números de tu operación.','Resumen de hasta las últimas 500 ventas registradas. Las ventas anuladas no suman.',btn('Exportar ventas','export-sales','outline'))}<div class="metric-grid">${[['Ventas netas',money(sum)],['Operaciones',sales.length],['Ticket promedio',money(sales.length?Math.round(sum/sales.length):0)],['Propinas',money(tips)]].map(([k,v])=>`<article class="metric glass"><span>${k}</span><strong>${v}</strong>${icon('reports')}</article>`).join('')}</div><div class="panel report-panel"><h3>Por medio de pago</h3><p class="help">Importes aplicados, incluidas las propinas.</p>${Object.entries(methods).map(([k,v])=>`<div class="report-row"><span>${esc(k)}</span><div><i style="width:${Math.round(v/(sum+tips||1)*100)}%"></i></div><strong>${money(v)}</strong></div>`).join('')||'<p class="empty">Los reportes aparecerán después de registrar ventas.</p>'}</div>`;}
function cashPage(){const s=state.shift;return`${intro('CONTROL DEL TURNO',s?'La caja está abierta.':'Todo comienza con una apertura.','Controla entradas, salidas y el efectivo contado al cerrar.',s?btn('Registrar movimiento','cash-movement','outline')+btn('Cerrar caja','cash-close','primary'):btn('Abrir caja','cash-open','primary'))}${s?`<div class="metric-grid"><article class="metric glass"><span>Fondo inicial</span><strong>${money(s.opening)}</strong></article><article class="metric glass"><span>Efectivo esperado</span><strong>${money(s.expected)}</strong></article><article class="metric glass"><span>Apertura</span><strong class="date-metric">${date(s.opened_at)}</strong></article></div>`:''}<div class="panel table-scroll"><h3>Movimientos recientes</h3><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Importe</th></tr></thead><tbody>${state.movements.map(m=>`<tr><td>${date(m.created_at)}</td><td>${esc(m.reason)}</td><td>${money(m.amount)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No hay movimientos.</td></tr>'}</tbody></table></div><div class="panel table-scroll"><h3>Cierres de caja</h3><table><thead><tr><th>Fecha</th><th>Esperado</th><th>Contado</th><th>Diferencia</th></tr></thead><tbody>${state.shifts.filter(s=>s.status==='closed').map(s=>`<tr><td>${date(s.closed_at)}</td><td>${money(s.expected)}</td><td>${money(s.counted)}</td><td>${money(s.difference)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Todavía no hay cierres.</td></tr>'}</tbody></table></div>`;}
function usersPage(){return`${intro('PERSONAS Y PERMISOS','Un rol para cada responsabilidad.','Las cuentas creadas aquí solo pertenecen a esta empresa.',btn('Agregar integrante','new-user','primary'))}<div class="panel table-scroll"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><span class="pill">${esc(u.role)}</span></td></tr>`).join('')}</tbody></table></div><div class="panel"><h3>Actividad reciente</h3><div class="audit-list">${state.audit.slice(0,30).map(a=>`<div><span>${esc(a.action)}</span><small>${date(a.created_at)}</small></div>`).join('')||'<p>Las operaciones quedarán registradas aquí.</p>'}</div></div>`;}
function settingsPage(){const s=state.tenant;logoValue=s.logo;return`${intro('LA IDENTIDAD DE TU NEGOCIO','Este espacio es tuyo.','Personaliza el nombre y la identidad que verá tu equipo.')}<form id="settings-form" class="panel settings-form"><div class="logo-settings"><div id="logo-preview">${s.logo?`<img src="${esc(s.logo)}" alt="Logo actual">`:`<span>${esc(s.name.slice(0,2))}</span>`}</div><label class="field"><span>Logo del negocio</span><input type="file" id="logo-file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG o WebP · máximo 2 MB</small></label>${btn('Quitar','clear-logo','quiet')}</div><div class="form-grid">${field('Nombre comercial','name',s.name,'text','required maxlength="150"')}${field('Razón social','legal_name',s.legal_name)}${field('Documento de la empresa','document',s.document)}${field('Dirección','address',s.address)}</div><button class="btn primary" type="submit">Guardar identidad ${icon('check')}</button><div class="subscription-info"><span class="eyebrow">ACCESO AL SERVICIO</span><p>Suscripción activa hasta ${date(s.expires_at)}.</p><small>La renovación y suspensión las administra Raven después de verificar el pago.</small></div></form>`;}
function openModal(title,html,form='generic-form'){modal.innerHTML=`<form id="${form}"><div class="modal-head"><h2>${title}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div>${html}<p class="modal-error error-text" role="alert"></p><div class="modal-actions">${btn('Cancelar','close-modal','outline')}<button type="submit" class="btn primary">Guardar</button></div></form>`;modal.showModal();}
function editProduct(id){const p=state.products.find(x=>x.id===id)||{price:0,cost:0,stock:0,track_stock:1,active:1};openModal(id?'Editar producto':'Nuevo producto',`<input type="hidden" name="id" value="${id||''}"><input type="hidden" name="version" value="${p.version||1}"><div class="form-grid">${field('Nombre','name',p.name,'text','required maxlength="150"')}${field('Categoría','category',p.category||'Platos','text','required')}${field('Precio S/','price',(p.price/100).toFixed(2),'number','required min="0" step="0.01"')}${field('Costo referencial S/','cost',(p.cost/100).toFixed(2),'number','required min="0" step="0.01"')}${field('Stock actual','stock',p.stock,'number','required min="0" step="1"')}${select('Imagen de ejemplo','image',[['','Sin imagen'],['burger','Hamburguesa'],['coffee','Café'],['salad','Ensalada'],['pizza','Pizza']],p.image)}</div><label class="check"><input name="track_stock" type="checkbox" ${p.track_stock?'checked':''}> Controlar existencias</label><label class="check"><input name="active" type="checkbox" ${p.active?'checked':''}> Producto activo</label><p class="help">Modificar el stock genera un registro de auditoría. Los pedidos existentes conservan su precio original.</p>`,'product-form');}
function editTable(id){const t=state.tables.find(x=>x.id===id)||{capacity:4,active:1};openModal(id?'Administrar mesa':'Agregar mesa',`<input name="id" type="hidden" value="${id||''}">${field('Nombre o número','name',t.name,'text','required maxlength="40"')}${field('Ambiente','area',t.area||'Salón principal','text','required')}${field('Capacidad','capacity',t.capacity,'number','required min="1" max="100"')}<label class="check"><input name="active" type="checkbox" ${t.active?'checked':''}> Mesa activa</label>`,'table-form');}
function editContact(id){const c=state.contacts.find(x=>x.id===id)||{};openModal(id?'Editar contacto':'Nuevo cliente / proveedor',`<input name="id" type="hidden" value="${id||''}"><div class="form-grid">${select('Tipo de documento','document_type',[['SIN DOCUMENTO','Sin documento'],['DNI','DNI'],['RUC','RUC'],['CE','Carné de extranjería']],c.document_type||'SIN DOCUMENTO')}${field('Número de documento','document',c.document)}${field('Nombre completo o razón social','name',c.name,'text','required')}${select('Tipo de contacto','type',[['cliente','Cliente'],['proveedor','Proveedor'],['ambos','Cliente y proveedor']],c.type||'cliente')}${field('Dirección','address',c.address)}${field('Correo','email',c.email,'email')}${field('Teléfono','phone',c.phone,'tel')}</div><p class="help">La información se ingresa manualmente. No se consulta SUNAT.</p>`,'contact-form');}
async function saveOrder(send=false){const result=await api(endpoint('orders'+(draft.id?'/'+draft.id:'')),{method:'POST',body:{...draft,send_kitchen:send}});draft=result;dirty=false;state=await api(endpoint('state'));render();return result;}
async function receipt(id){const r=await api(endpoint('receipt/'+id));const content=`<div class="receipt"><h2>${esc(r.settings.name)}</h2><p>${esc(r.settings.legal_name)}<br>${esc(r.settings.address)}</p><strong>${r.sale?'TICKET INTERNO':'PRECUENTA'} #${r.sale?.number||r.order.number}</strong><p>${date(r.sale?.created_at||r.order.created_at)}<br>${esc(r.customer?.name||'Consumidor final')}</p>${r.sale?.status==='void'?'<h2>ANULADO</h2>':''}<table><tbody>${r.order.items.map(i=>`<tr><td>${i.quantity} × ${esc(i.name)}</td><td>${money(i.quantity*i.price)}</td></tr>`).join('')}</tbody></table><p>Descuento: ${money(r.order.discount)}</p><h3>Total ${money(r.order.total)}</h3>${r.sale?`<p>Propina ${money(r.sale.tip)}</p>${r.sale.payments.map(p=>`<p>${esc(p.method)}: ${money(p.amount)}${p.change?' · vuelto '+money(p.change):''}</p>`).join('')}`:''}<small>Documento interno sin validez tributaria.<br>No es boleta ni factura electrónica.</small></div>`;modal.innerHTML=`<div class="modal-head"><h2>Documento</h2>${btn('×','close-modal','icon-btn','aria-label="Cerrar"')}</div>${content}<div class="modal-actions">${btn('Descargar texto','download-receipt','outline')}${btn(icon('print')+' Imprimir','print','primary')}</div>`;modal.showModal();}
function download(name,content,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function readLogo(event){const f=event.target.files[0];if(!f)return;if(f.size>2000000||!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('Usa PNG, JPEG o WebP de hasta 2 MB.',true);return;}const reader=new FileReader();reader.onload=()=>{logoValue=reader.result;$('#logo-preview').innerHTML=`<img src="${esc(logoValue)}" alt="Vista previa del logo">`;};reader.readAsDataURL(f);}
function leave(){return !dirty||confirm('Hay cambios sin guardar en este pedido. ¿Quieres salir sin guardarlos?');}
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action]');if(!button||button.disabled||busy||submitting)return;event.preventDefault();const a=button.dataset.action,id=button.dataset.id;
 try{
  if(a==='logout'){if(!leave())return;await api('logout',{method:'POST',body:{}});me=null;draft=null;login();}
  if(a==='companies'){if(!leave())return;me=await api('me');companies();}
  if(a==='company'){tenant=me.tenants.find(t=>t.id===id);state=await api(endpoint('state'));view=state.permissions.includes('orders')?'tables':state.role==='cocina'?'kitchen':'products';render();}
  if(a==='view'){if(!leave())return;draft=null;dirty=false;view=button.dataset.view;await refresh();}
  if(a==='refresh'){if(draft&&dirty){toast('Guarda el pedido antes de actualizar.',true);return;}if(draft?.id){state=await api(endpoint('state'));draft=structuredClone(state.orders.find(o=>o.id===draft.id)||null);render();}else await refresh();}
  if(a==='new-order'||a==='new-quote'){if(!leave())return;newDraft();if(a==='new-quote'){draft.status='quote';render();}}
  if(a==='table'){const existing=state.orders.find(o=>o.table_id===id&&o.status==='open');if(existing){draft=structuredClone(existing);dirty=false;render();}else newDraft(id);}
  if(a==='load-order'){draft=structuredClone(state.orders.find(o=>o.id===id));editorTab='products';dirty=false;render();}
  if(a==='back'){if(!leave())return;draft=null;dirty=false;view='tables';await refresh();}
  if(a==='add-product'){const p=state.products.find(p=>p.id===id),line=draft.items.find(i=>i.product_id===id);if(line)line.quantity++;else draft.items.push({product_id:id,name:p.name,price:p.price,quantity:1,note:''});dirty=true;render();}
  if(a==='quantity'){const line=draft.items[Number(button.dataset.index)];line.quantity+=Number(button.dataset.delta);if(line.quantity<1)draft.items.splice(Number(button.dataset.index),1);dirty=true;render();}
  if(a==='remove-item'){draft.items.splice(Number(button.dataset.index),1);dirty=true;render();}
  if(a==='table-filter'){tableFilter=button.dataset.filter;render();}
  if(a==='catalog-list'||a==='catalog-grid'){catalogView=a==='catalog-list'?'list':'grid';render();}
  if(a==='focus-tip')$('#payment-form [name=tip]').focus();
  if(a==='finalize'){if(editorTab==='payments')$('#payment-form').requestSubmit();else{editorTab='payments';render();}}
  if(a==='line-note'){const index=Number(button.dataset.index);openModal('Observaciones del producto',field('Indicaciones','note',draft.items[index].note,'text','maxlength="250"')+'<input type="hidden" name="index" value="'+index+'">','line-note-form');}
  if(a==='toggle-table'){const t=state.tables.find(t=>t.id===id);if(confirm('¿'+(t.active?'Desactivar':'Activar')+' la mesa '+t.name+'?'))await mutate('tables/'+id,{...t,active:!t.active});}
  if(a==='manage-tables'){openModal('Administrar mesas','<div class="manage-table-list">'+state.tables.map(t=>'<div><span>Mesa '+esc(t.name)+' · '+esc(t.area)+'</span>'+btn(t.active?'Editar':'Reactivar','manage-one','outline','data-id="'+t.id+'"')+'</div>').join('')+'</div>','manage-form');}
  if(a==='manage-one'){const t=state.tables.find(t=>t.id===id);modal.close();if(t.active)editTable(id);else await mutate('tables/'+id,{...t,active:true});}
  if(a==='category'){category=button.dataset.category;render();}
  if(a==='products-tab'||a==='pay-tab'){if(a==='pay-tab'&&!draft.items.length)return;editorTab=a==='pay-tab'?'payments':'products';render();}
  if(a==='save-order'||a==='send-kitchen'){busy=true;await saveOrder(a==='send-kitchen');toast(a==='send-kitchen'?'Pedido enviado a cocina.':'Pedido guardado.');}
  if(a==='convert-quote'){draft.status='open';dirty=true;await saveOrder();toast('Cotización convertida a pedido.');}
  if(a==='order-options')openModal('Opciones del pedido',`${select('Mesa','table_id',[['','Mostrador / sin mesa'],...state.tables.filter(t=>t.active).map(t=>[t.id,t.area+' · Mesa '+t.name])],draft.table_id||'')}${select('Cliente','customer_id',[['','Consumidor final'],...state.contacts.filter(c=>c.type!=='proveedor').map(c=>[c.id,c.name])],draft.customer_id||'')}${field('Personas','guests',draft.guests,'number','min="1" max="100" required')}${can('checkout')?field('Descuento S/','discount',((draft.discount||0)/100).toFixed(2),'number','min="0" step="0.01"'):''}<label class="field"><span>Notas para cocina</span><textarea name="notes" maxlength="1000">${esc(draft.notes)}</textarea></label>${draft.id?btn('Cancelar este pedido','cancel-order','danger'):''}`,'order-options-form');
  if(a==='cancel-order'){const reason=prompt('Motivo de cancelación:');if(!reason)return;await mutate('orders/'+draft.id,{version:draft.version,cancel:true,reason});draft=null;dirty=false;modal.close();await refresh();}
  if(a==='add-payment'){$('.payment-rows').insertAdjacentHTML('beforeend',`<div class="payment-row">${select('Medio','method',[['efectivo','Efectivo'],['tarjeta','Tarjeta'],['yape','Yape'],['plin','Plin'],['transferencia','Transferencia']])}${field('Importe aplicado','amount','','number','min="0.01" step="0.01" required')}${btn('×','remove-payment','quiet','aria-label="Quitar pago"')}</div>`);}
  if(a==='remove-payment')button.closest('.payment-row').remove();
  if(a==='edit-product')editProduct(id);
  if(a==='edit-table')editTable(id);
  if(a==='edit-contact')editContact(id);
  if(a==='close-modal')modal.close();
  if(a==='new-purchase')openModal('Registrar recepción de compra',`${select('Producto','product_id',state.products.map(p=>[p.id,p.name]))}${select('Proveedor','supplier_id',[['','Sin proveedor'],...state.contacts.filter(c=>c.type!=='cliente').map(c=>[c.id,c.name])])}${field('Cantidad recibida','quantity',1,'number','min="1" required')}${field('Total de la compra S/','total','','number','min="0.01" step="0.01" required')}${field('Referencia del documento','reference')}<p class="help">Aumenta existencias. Registra el pago en Caja si corresponde.</p>`,'purchase-form');
  if(a==='new-user')openModal('Agregar integrante',`${field('Nombre','name','','text','required')}${field('Correo','email','','email','required')}${field('Contraseña inicial','password','','password','required minlength="12" autocomplete="new-password"')}${select('Rol','role',[['mesero','Mesero'],['cajero','Cajero'],['cocina','Cocina'],['almacen','Almacén'],['admin','Administrador']])}<p class="help">Acceso exclusivo a ${esc(state.tenant.name)}. Mínimo 12 caracteres.</p>`,'user-form');
  if(a==='cash-open')openModal('Abrir caja',field('Fondo inicial S/','opening','0.00','number','required min="0" step="0.01"'),'cash-open-form');
  if(a==='cash-movement')openModal('Movimiento de efectivo',`${select('Tipo','type',[['in','Entrada'],['out','Salida']])}${field('Importe S/','amount','','number','required min="0.01" step="0.01"')}${field('Motivo','reason','','text','required')}`,'cash-movement-form');
  if(a==='cash-close')openModal('Cerrar caja',`<p>Efectivo esperado: <strong>${money(state.shift.expected)}</strong></p>${field('Efectivo contado S/','counted','','number','required min="0" step="0.01"')}<p class="help">El cierre conserva la diferencia y no se puede editar.</p>`,'cash-close-form');
  if(a==='kitchen-next'){const o=state.orders.find(o=>o.id===id);await mutate('kitchen/'+id,{version:o.version,status:{received:'preparing',preparing:'ready',ready:'served'}[o.kitchen]},'Estado de cocina actualizado.');}
  if(a==='void'){const reason=prompt('Motivo de anulación (se conserva en auditoría):');if(reason&&confirm('¿Anular esta venta y reponer el stock?'))await mutate('void/'+id,{reason},'Venta anulada.');}
  if(a==='receipt')await receipt(id);
  if(a==='prebill'){if(dirty){toast('Guarda los cambios antes de preparar la precuenta.',true);return;}await receipt(draft.id);}
  if(a==='print')window.print();
  if(a==='download-receipt')download('raven-ticket-interno.txt',$('.receipt').innerText);
  if(a==='export-sales'){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';download('raven-ventas.csv','\uFEFF'+[['Venta','Fecha','Total PEN','Propina PEN','Estado'],...state.sales.map(s=>[s.number,s.created_at,(s.total/100).toFixed(2),(s.tip/100).toFixed(2),s.status])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');}
  if(a==='clear-logo'){logoValue='';$('#logo-preview').textContent=state.tenant.name.slice(0,2);}
 }catch(error){toast(error.message,true);}finally{busy=false;document.body.classList.remove('busy');}
});
document.addEventListener('submit',async event=>{
 const form=event.target;event.preventDefault();if(busy||submitting)return;submitting=true;const d=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
 try{
  if(form.id==='login-form'){await api('login',{method:'POST',body:d});me=await api('me');companies();return;}
  if(form.id==='product-form')await mutate('products'+(d.id?'/'+d.id:''),{...d,price:cents(d.price),cost:cents(d.cost),version:Number(d.version),stock:Number(d.stock),track_stock:d.track_stock==='on',active:d.active==='on'});
  if(form.id==='line-note-form'){draft.items[Number(d.index)].note=d.note;dirty=true;render();}
  if(form.id==='table-form')await mutate('tables'+(d.id?'/'+d.id:''),{...d,capacity:Number(d.capacity),active:d.active==='on'});
  if(form.id==='contact-form')await mutate('contacts'+(d.id?'/'+d.id:''),d);
  if(form.id==='purchase-form')await mutate('purchases',{...d,quantity:Number(d.quantity),total:cents(d.total)});
  if(form.id==='user-form')await mutate('users',d,'Integrante creado.');
  if(form.id==='cash-open-form')await mutate('cash/open',{opening:cents(d.opening)},'Caja abierta.');
  if(form.id==='cash-movement-form')await mutate('cash/movement',{...d,amount:cents(d.amount)});
  if(form.id==='cash-close-form')await mutate('cash/close',{counted:cents(d.counted)},'Caja cerrada.');
  if(form.id==='settings-form'){await mutate('settings',{...d,logo:logoValue},'Identidad actualizada.');return;}
  if(form.id==='order-options-form'){draft={...draft,table_id:d.table_id||null,customer_id:d.customer_id||null,guests:Number(d.guests),discount:can('checkout')?cents(d.discount):draft.discount,notes:d.notes};dirty=true;render();}
  if(form.id==='payment-form'){
    const rows=[...form.querySelectorAll('.payment-row')];const payments=rows.map(row=>({method:row.querySelector('[name=method]').value,amount:cents(row.querySelector('[name=amount]').value)}));if(d.received){const cash=payments.filter(p=>p.method==='efectivo');if(cash.length!==1)throw Error('Para calcular vuelto usa un solo pago en efectivo.');cash[0].received=cents(d.received);}const tip=cents(d.tip);if(payments.reduce((s,p)=>s+p.amount,0)!==total()+tip)throw Error('Los pagos deben sumar el pedido más la propina.');
    draft.customer_id=d.customer_id||null;busy=true;await saveOrder();const result=await api(endpoint('checkout/'+draft.id),{method:'POST',body:{version:draft.version,payments,tip}});draft=null;dirty=false;view='sales';await refresh();await receipt(result.order_id);toast('Venta registrada. Mesa liberada y stock actualizado.');return;
  }
  modal.close();
 }catch(error){const box=form.querySelector('.modal-error')||$('#login-error');if(box)box.textContent=error.message;toast(error.message,true);}finally{submitting=false;busy=false;if(submit)submit.disabled=false;document.body.classList.remove('busy');}
});
document.addEventListener('change',event=>{if(event.target.name==='area-filter'){selectedArea=event.target.value;render();}});
document.addEventListener('keydown',event=>{const tab=event.target.closest('.editor-tabs [role=tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const tabs=[...document.querySelectorAll('.editor-tabs [role=tab]:not(:disabled)')];if(tabs.length<2)return;event.preventDefault();const next=event.key==='Home'?tabs[0]:event.key==='End'?tabs.at(-1):tabs[(tabs.indexOf(tab)+(event.key==='ArrowLeft'?tabs.length-1:1))%tabs.length];const action=next.dataset.action;next.click();document.querySelector('[data-action="'+action+'"]').focus();});
document.addEventListener('input',event=>{if(!event.target.closest('#payment-form'))return;try{const form=$('#payment-form');const applied=[...form.querySelectorAll('[name=amount]')].reduce((s,x)=>s+cents(x.value||'0'),0);const tip=cents(form.querySelector('[name=tip]').value||'0');const remaining=total()+tip-applied;const cashRows=[...form.querySelectorAll('.payment-row')].filter(row=>row.querySelector('[name=method]').value==='efectivo');const received=form.querySelector('[name=received]').value;let message=remaining>0?'Pendiente '+money(remaining):remaining<0?'Exceso '+money(-remaining):'Pago completo';if(received&&cashRows.length===1){const change=cents(received)-cents(cashRows[0].querySelector('[name=amount]').value||'0');message+=change>=0?' · Vuelto '+money(change):' · Efectivo insuficiente';}form.querySelector('.payment-feedback').textContent=message;}catch{}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
boot();
